const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(d,opts)=>new Intl.DateTimeFormat('cs-CZ',{timeZone:'Europe/Prague',...opts}).format(new Date(d));
const key='vitkovice-vip-kiosk-v1';
let state={entries:[],results:{},closedMatches:{}};
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&Array.isArray(saved.entries)&&saved.results&&typeof saved.results==='object')state=saved}catch{}
state.closedMatches=state.closedMatches&&typeof state.closedMatches==='object'?state.closedMatches:{};
let currentId=matches.some(m=>m.id===state.activeMatchId)?state.activeMatchId:(matches.find(m=>new Date(m.date)>new Date())?.id||matches.at(-1).id);
state.activeMatchId=currentId;
try{localStorage.setItem(key,JSON.stringify(state))}catch{}

let outcome='',screen='welcome',timer,lastActivity=Date.now();
const current=()=>matches.find(m=>m.id===currentId);
const started=m=>Date.now()>=new Date(m.date).getTime();
const closed=m=>Boolean(state.closedMatches[m.id]||state.results[m.id]);
const open=m=>started(m)&&!closed(m);

const entries=id=>state.entries.filter(e=>e.matchId===id);
function persist(next){try{localStorage.setItem(key,JSON.stringify(next));state=next;return true}catch{message('Uložení se nezdařilo. Požádej obsluhu o pomoc.');return false}}
function message(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',5000)}
function matchLine(m){return `Vítkovice Ridera <span class="versus">vs.</span> ${esc(m.opponent)}`}
function selectMatch(){return `<label class="field-label" for="match">Aktivní zápas pro celý kiosek</label><select id="match">${matches.map(m=>`<option value="${m.id}" ${m.id===currentId?'selected':''}>${fmt(m.date,{day:'numeric',month:'numeric',hour:'2-digit',minute:'2-digit'})} · ${esc(m.opponent)}</option>`).join('')}</select><p class="hint">Změna se uloží pro všechny další návštěvníky tohoto zařízení. Návštěvníci zápas nevybírají.</p>`}
function matchCard(){const m=current();return `<section class="hero featured-match" aria-label="Zápas této VIP soutěže"><div class="hero-top"><span>DNEŠNÍ VIP SOUTĚŽ · ${m.round}. KOLO</span><span class="live" id="match-status">${closed(m)?'● TIPOVÁNÍ UZAVŘENO':started(m)?'● TIPOVÁNÍ OTEVŘENO':'● ČEKÁME NA ZAČÁTEK'}</span></div><div class="matchup"><div class="team"><img src="${logo}" alt="HC Vítkovice Ridera"><strong>VÍTKOVICE RIDERA</strong><small>DOMÁCÍ</small></div><span class="versus">VS</span><div class="team"><div class="opponent-mark">${esc(m.id.toUpperCase())}</div><strong>${esc(m.short)}</strong><small>HOSTÉ</small></div></div><div class="match-info">${fmt(m.date,{day:'numeric',month:'long',year:'numeric'})} &nbsp; / &nbsp; ${fmt(m.date,{hour:'2-digit',minute:'2-digit'})} &nbsp; / &nbsp; Domácí led</div><div class="countdown"><span id="countdown-label">${closed(m)?'Soutěž tohoto zápasu skončila':started(m)?'Tipujeme do konce 3. třetiny':'Tipování se otevře za'}</span><b id="countdown" role="timer">${countdownText(m)}</b></div></section>`}
function countdownText(m){if(closed(m))return 'TIPY UZAVŘENY';if(started(m))return 'ZAPOJ SE DO HRY';const seconds=Math.max(0,Math.ceil((new Date(m.date)-Date.now())/1000));return `${Math.floor(seconds/86400)} d : ${String(Math.floor(seconds/3600)%24).padStart(2,'0')} h : ${String(Math.floor(seconds/60)%60).padStart(2,'0')} m : ${String(seconds%60).padStart(2,'0')} s`}

function winnersMarkup(m){const result=state.results[m.id];if(!result)return '<p>Výsledek zatím není potvrzený. Po vyhodnocení zde vyhlásíme vítěze.</p>';const winners=Competition.evaluate(entries(m.id),result);return `<div class="final-score">${result.home} : ${result.away}</div><p>Výsledek po 60 minutách</p>${winners.length?`<span class="eyebrow">${winners[0].distance===0?'PŘESNÝ TIP':'NEJBLIŽŠÍ TIP'}</span><h1>${winners.length===1?'Gratulujeme vítězi!':'Gratulujeme vítězům!'}</h1><div class="winner-names">${winners.map(e=>`<div>${esc(e.name)} <small>tip ${e.home} : ${e.away}</small></div>`).join('')}</div><p class="prize">Cenu si vyzvedněte ve VIP zóně.</p>`:'<h1>Tento zápas nemá žádné tipy.</h1>'}`}
function welcome(){screen='welcome';outcome='';$('#main').innerHTML=`<section class="attract"><img class="attract-logo" src="${logo}" alt="HC Vítkovice Ridera"><span class="eyebrow">EXKLUZIVNĚ PRO HOSTY VIP ZÓNY</span><h1>Na ledě tým.<br>Ve hře ty.</h1><p>Tipni skóre. Užij si zápas. Vyhraj cenu.</p>${matchCard()}<button class="touch-start" data-action="start">☝ <span>Dotkni se obrazovky<small>${open(current())?'a zapoj se do tipovací soutěže':'a prohlédni si dnešní zápas'}</small></span> →</button><button class="text-button" data-action="winners">Výsledky a vítězové →</button><div class="attract-bottom">JEDEN TÝM. JEDNO SRDCE. <span>HC VÍTKOVICE RIDERA</span></div></section>`}
function form(){screen='form';outcome='';const m=current();$('#main').innerHTML=`<div class="kiosk-head"><button class="text-button" data-action="home">← Úvod</button><span class="eyebrow">VIP TIPOVACÍ SOUTĚŽ</span><button class="text-button" data-action="rules">Pravidla</button></div><section class="kiosk-card"><span class="eyebrow">${open(m)?'TVŮJ TIP NA DOMÁCÍ ZÁPAS':closed(m)?'TIPOVÁNÍ UZAVŘENO':'TIPOVÁNÍ SE BRZY OTEVŘE'}</span><h1>${matchLine(m)}</h1><p class="hint">${fmt(m.date,{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})} · Tipujeme po 60 minutách, bez prodloužení a nájezdů.</p>${matchCard()}${!open(m)?`<div class="notice">${closed(m)?'Tipování tohoto zápasu skončilo. Podívej se na výsledky a vítěze.':'Tipování se otevře při plánovaném začátku zápasu a poběží do konce 3. třetiny.'}</div><button class="primary" data-action="winners">Výsledky a vítězové →</button>`:`<form id="entry-form" autocomplete="off"><label class="field-label" for="guest-name">1. Jak se jmenuješ?</label><input id="guest-name" name="name" type="text" minlength="2" maxlength="60" required autocomplete="off" placeholder="Tvé jméno a příjmení"><label class="field-label">2. Jak zápas dopadne?</label><div class="choices">${[['1','Vyhrají Vítkovice'],['X','Remíza'],['2','Vyhrají hosté']].map(([v,label])=>`<button type="button" data-outcome="${v}" class="choice" aria-pressed="false"><b>${v}</b>${label}</button>`).join('')}</div><div class="form-row"><div><label class="field-label" for="home-score">3. Tipni přesné skóre</label><div class="score"><div><input id="home-score" aria-label="Góly Vítkovic" type="number" inputmode="numeric" min="0" max="30" required placeholder="0"><small>Vítkovice</small></div><span>:</span><div><input id="away-score" aria-label="Góly soupeře" type="number" inputmode="numeric" min="0" max="30" required placeholder="0"><small>Hosté</small></div></div></div><div><label class="field-label" for="goals">4. Kolik padne gólů? <small>(volitelné)</small></label><select id="goals"><option value="">Bez dalšího tipu</option><option value="under">0 až 5 gólů (pod 5,5)</option><option value="over">6 a více gólů (nad 5,5)</option></select></div></div><p class="hint">Jméno použijeme k vyhlášení vítěze na této obrazovce. Jeden tip na jméno a zápas na tomto kiosku. Při shodě vyhrávají všichni stejně úspěšní.</p><div class="submit-row"><button type="button" class="text-button" data-action="rules">Jak vybíráme vítěze?</button><button class="primary">Potvrdit můj tip →</button></div></form>`}</section>`}
function resultScreen(){screen='winners';const m=current();$('#main').innerHTML=`<div class="kiosk-head"><button class="text-button" data-action="home">← Úvod</button><span class="eyebrow">VIP TIPOVACÍ SOUTĚŽ</span><button class="text-button" data-action="rules">Pravidla</button></div><section class="kiosk-card results-screen">${matchCard()}<h2>${matchLine(m)}</h2>${winnersMarkup(m)}<button class="primary" data-action="home">Zpět na úvod →</button></section>`}
function thanks(entry){screen='thanks';$('#main').innerHTML=`<section class="attract confirmation"><span class="confirmation-icon">✓</span><span class="eyebrow">TIP JE ULOŽENÝ</span><h1>Díky za tip,<br>${esc(entry.name)}!</h1><p>${matchLine(current())}</p><div class="final-score">${entry.home} : ${entry.away}</div><p>Po zápase vyhlásíme vítěze.<br>Cenu si vítěz vyzvedne ve VIP zóně.</p><button class="touch-start" data-action="home">Další návštěvník →</button><small>Za 12 sekund se obrazovka vrátí na úvod.</small></section>`;setTimeout(()=>{if(screen==='thanks')welcome()},12000)}
function rules(){ $('#dialog-content').innerHTML='<span class="eyebrow">PRAVIDLA VIP SOUTĚŽE</span><h1>Jak vybereme vítěze?</h1><ol><li>Vyber výsledek 1 / X / 2 a přesné skóre po 60 minutách. Remíza je platný tip.</li><li>Vyhrává přesné skóre. Pokud jej nikdo netrefí, vyhrává nejmenší součet odchylek obou skóre. Pro výsledek 2:1 má tip 3:1 odchylku 1.</li><li>Při stejné odchylce rozhodne správný doplňkový tip na počet gólů (0–5 / 6 a více). I mezi přesnými tipy.</li><li>Při další shodě vyhlašujeme všechny společné vítěze. Rozdělení cen zajistí obsluha VIP zóny.</li><li>Jeden tip na jméno a utkání na tomto zařízení. Tip nelze po potvrzení měnit. Jméno není ověřená totožnost.</li><li>Tipování začíná v plánovaný začátek zápasu a končí po 3. třetině. Konec 3. třetiny zde potvrzuje obsluha, živý stav utkání zatím není připojený. Při odložení pořadatel musí termín nejprve opravit; automatické změny zatím nejsou připojené.</li></ol><p>Místní prototyp: tipy zůstávají v tomto prohlížeči. Výsledek ručně potvrzuje obsluha. Ceny a finální pravidla schvaluje pořadatel.</p>';$('#dialog').showModal()}
function staff(){screen='staff';const m=current();$('#main').innerHTML=`<div class="kiosk-head"><button class="text-button" data-action="home">← Kiosek</button><span class="eyebrow">OBSLUHA · MÍSTNÍ PROTOTYP</span></div><section class="kiosk-card"><h1>Vyhodnocení zápasu</h1><div class="notice">Tato místní administrace není chráněná přihlášením. Pro ostrý provoz je potřeba server a samostatný přístup obsluhy. Výsledek zadejte až po skončení základní hrací doby.</div>${selectMatch()}${started(m)&&!closed(m)?'<button class="primary close-competition" data-action="close-tipping">Konec 3. třetiny — uzavřít tipy</button><p class="hint">Stiskněte při skončení třetí třetiny, před zadáním výsledku. Poté už kiosek nepřijme žádný tip.</p>':''}<p class="hint">${entries(m.id).length} přijatých tipů na tomto zařízení</p>${state.results[m.id]?`<h2>Potvrzený výsledek: ${state.results[m.id].home} : ${state.results[m.id].away}</h2><p class="hint">Výsledek je uzamčený. Vyhlášení vítězů najdete v kiosku.</p><button class="primary" data-action="winners">Zobrazit vítěze →</button>`:`<form id="result-form"><label class="field-label">Potvrzený výsledek po 60 minutách</label><div class="score"><input id="result-home" aria-label="Skutečné góly Vítkovic" type="number" min="0" max="30" inputmode="numeric" required><span>:</span><input id="result-away" aria-label="Skutečné góly soupeře" type="number" min="0" max="30" inputmode="numeric" required></div><label class="confirm-label"><input id="result-confirm" type="checkbox" required> Ověřil/a jsem výsledek po 60 minutách a chci vyhlásit vítěze.</label><button class="primary" ${!closed(m)?'disabled':''}>Potvrdit výsledek a vyhodnotit →</button><p class="hint">${!closed(m)?'Nejdříve uzavřete tipování tlačítkem Konec 3. třetiny.':'Tipování je uzavřené. Potvrďte výsledek po dohrání 60 minut.'}</p></form>`}</section>`}
function submitEntry(){const m=current();if(!open(m)){message(closed(m)?'Tipování je už uzavřené.':'Tipování se otevře při začátku zápasu.');form();return}const h=$('#home-score').value,a=$('#away-score').value;const entry={id:crypto.randomUUID(),matchId:m.id,name:$('#guest-name').value.trim().replace(/\s+/g,' '),outcome,home:h===''?null:Number(h),away:a===''?null:Number(a),goals:$('#goals').value,savedAt:new Date().toISOString()};const error=Competition.validate(entry);if(error){message(error);return}const normalized=s=>s.normalize('NFKC').toLocaleLowerCase('cs-CZ');if(entries(m.id).some(e=>normalized(e.name)===normalized(entry.name))){message('Na toto jméno už je pro tento zápas tip uložený. Při shodě jmen se obrať na obsluhu.');return}if(persist({...state,entries:[...state.entries,entry]}))thanks(entry)}
function submitResult(){const m=current();if(!closed(m)||state.results[m.id]){message('Tento zápas teď nelze vyhodnotit.');return}const h=$('#result-home').value,a=$('#result-away').value;const result={home:h===''?null:Number(h),away:a===''?null:Number(a),confirmedAt:new Date().toISOString()};if(!Competition.validScore(result.home)||!Competition.validScore(result.away)||!$('#result-confirm').checked){message('Vyplň skóre a potvrď ověření výsledku.');return}if(persist({...state,results:{...state.results,[m.id]:result}}))resultScreen()}
function home(){currentId=state.activeMatchId;lastActivity=Date.now();if($('#dialog').open)$('#dialog').close();if(location.hash)history.replaceState(null,'',location.pathname+location.search);welcome()}
$('#main').addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='entry-form')submitEntry();if(event.target.id==='result-form')submitResult()});
$('#main').addEventListener('change',event=>{if(event.target.id==='match'&&screen==='staff'&&matches.some(m=>m.id===event.target.value)){if(persist({...state,activeMatchId:event.target.value})){currentId=event.target.value;staff()}else event.target.value=currentId}});
$('#main').addEventListener('click',event=>{const b=event.target.closest('[data-outcome]');if(b){outcome=b.dataset.outcome;document.querySelectorAll('[data-outcome]').forEach(el=>{el.classList.toggle('selected',el.dataset.outcome===outcome);el.setAttribute('aria-pressed',String(el.dataset.outcome===outcome))})}const action=event.target.closest('[data-action]')?.dataset.action;if(action==='close-tipping'&&screen==='staff'&&started(current())&&!closed(current())){if(persist({...state,closedMatches:{...state.closedMatches,[currentId]:new Date().toISOString()}}))staff()}if(action==='start')form();if(action==='home')home();if(action==='winners')resultScreen();if(action==='rules')rules()});
$('#rules').onclick=rules;$('.close').onclick=()=>$('#dialog').close();
for(const type of ['pointerdown','keydown','input'])document.addEventListener(type,()=>lastActivity=Date.now());
let lastMatchPhase=closed(current())?'closed':started(current())?'open':'waiting';
setInterval(()=>{
  if(!['welcome','staff'].includes(screen)&&Date.now()-lastActivity>90000)home();
  const m=current(),phase=closed(m)?'closed':started(m)?'open':'waiting';
  if($('#countdown'))$('#countdown').textContent=countdownText(m);
  if(lastMatchPhase&&phase!==lastMatchPhase){if(screen==='form')form();if(screen==='welcome')welcome();if(screen==='staff')staff()}
  lastMatchPhase=phase;
},1000);
addEventListener('hashchange',()=>location.hash==='#obsluha'?staff():home());
location.hash==='#obsluha'?staff():welcome();
